// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newAdmin, bool access, bytes4 dummyInterface) public {
        // bound dummyInterface to avoid uninteresting variations
        dummyInterface = bytes4(keccak256(abi.encodePacked(dummyInterface)));
        vm.assume(dummyInterface != 0x01ffc9a7); // We'll test IERC165 separately

        // First, test IERC165 support directly
        vm.prank(address(this));
        c.adjustAdminAccess(newAdmin, access);

        // The core rule: supportsInterface returns true for IERC165 (0x01ffc9a7)
        assertTrue(c.supportsInterface(0x01ffc9a7));
    }
}

